const item = $input.first().json;
const data = item.data || {};

// Content QA Validation Rules
const caption = data.caption || data.content || '';
const hashtags = data.hashtags || '';
const bannedWords = ['guaranteed profits', 'get rich quick', '100% free money', 'miracle solution'];

let hasBanned = false;
for (const w of bannedWords) {
  if (caption.toLowerCase().includes(w)) {
    hasBanned = true;
    break;
  }
}

const lengthValid = caption.length > 50 && caption.length <= 3000;
const passed = !hasBanned && lengthValid;

return {
  json: {
    topic: item.topic,
    caption: caption,
    hashtags: hashtags,
    qa_passed: passed,
    qa_notes: passed ? 'QA passed automatically' : (hasBanned ? 'Banned keyword detected' : 'Length invalid'),
    status: passed ? 'DRAFTED' : 'FAILED'
  }
};
